289: /** chainable, internal
290:  * MarkdownIt.configure(presets)
291:  *
292:  * Batch load of all options and compenent settings. This is internal method,
293:  * and you probably will not need it. But if you with - see available presets
294:  * and data structure [here](https://github.com/markdown-it/markdown-it/tree/master/lib/presets)
295:  *
296:  * We strongly recommend to use presets instead of direct config loads. That
297:  * will give better compatibility with next versions.
298:  **/
299: MarkdownIt.prototype.configure = function (presets) {
300:   var self = this, presetName;
301: 
302:   if (utils.isString(presets)) {
303:     presetName = presets;
304:     presets = config[presetName];
305:     if (!presets) { throw new Error('Wrong `markdown-it` preset "' + presetName + '", check name'); }
306:   }
307: 
308:   if (!presets) { throw new Error('Wrong `markdown-it` preset, can\'t be empty'); }
309: 
310:   if (presets.options) { self.set(presets.options); }
311: 
312:   if (presets.components) {
313:     Object.keys(presets.components).forEach(function (name) {
314:       if (presets.components[name].rules) {
315:         self[name].ruler.enableOnly(presets.components[name].rules);
316:       }
317:     });
318:   }
319:   return this;
320: };
