323: /** chainable
324:  * MarkdownIt.enable(list, ignoreInvalid)
325:  * - list (String|Array): rule name or list of rule names to enable
326:  * - ignoreInvalid (Boolean): set `true` to ignore errors when rule not found.
327:  *
328:  * Enable list or rules. It will automatically find appropriate components,
329:  * containing rules with given names. If rule not found, and `ignoreInvalid`
330:  * not set - throws exception.
331:  *
332:  * ##### Example
333:  *
334:  * ```javascript
335:  * var md = require('markdown-it')()
336:  *             .enable(['sub', 'sup'])
337:  *             .disable('smartquotes');
338:  * ```
339:  **/
340: MarkdownIt.prototype.enable = function (list, ignoreInvalid) {
341:   var result = [];
342: 
343:   if (!Array.isArray(list)) { list = [ list ]; }
344: 
345:   [ 'core', 'block', 'inline' ].forEach(function (chain) {
346:     result = result.concat(this[chain].ruler.enable(list, true));
347:   }, this);
348: 
349:   var missed = list.filter(function (name) { return result.indexOf(name) < 0; });
350: 
351:   if (missed.length && !ignoreInvalid) {
352:     throw new Error('MarkdownIt. Failed to enable unknown rule(s): ' + missed);
353:   }
354: 
355:   return this;
356: };
